import{_ as t,o as a,c as l,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Agent Skill","description":"","frontmatter":{},"headers":[],"relativePath":"zh/developers/skill.md","filePath":"zh/developers/skill.md","lastUpdated":1792570296000}'),o={name:"zh/developers/skill.md"};function i(n,e,p,s,d,k){return a(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="agent-skill" tabindex="-1">Agent Skill <a class="header-anchor" href="#agent-skill" aria-label="Permalink to &quot;Agent Skill&quot;">​</a></h1><p>在支持 Skill、能够运行本地命令的 Agent 中使用 PaperSeek。Skill 指导 Agent 检查安装、配置环境、执行文献检索，并读取已保存的结果。</p><p>检索在本地社区版中执行，历史与产物保存在其本地存储中；模型和数据源请求使用你配置的服务。不需要 PaperSeek 账户。</p><h2 id="添加-skill" tabindex="-1">添加 Skill <a class="header-anchor" href="#添加-skill" aria-label="Permalink to &quot;添加 Skill&quot;">​</a></h2><p>Skill 位于仓库的 <a href="https://github.com/paperseek/paperseek/tree/main/integrations/skills/paperseek" target="_blank" rel="noreferrer">integrations/skills/paperseek</a>。</p><ol><li>通过 Agent 的 Skill 安装功能添加该目录，或将完整的 <code>paperseek</code> 文件夹复制到客户端规定的项目级或用户级 Skill 目录。</li><li>保持 <code>SKILL.md</code> 与 <code>references/</code> 目录在一起。参考文件包含安装步骤、受支持的命令和数据源选项。</li><li>如客户端要求，重新加载 Skill，并确认它识别到名称 <strong>paperseek</strong>。</li></ol><p>可以先添加 Skill，再安装社区版。复制 Skill 本身不会安装 Python、PaperSeek 或模型凭据。</p><h2 id="首次使用" tabindex="-1">首次使用 <a class="header-anchor" href="#首次使用" aria-label="Permalink to &quot;首次使用&quot;">​</a></h2><p>直接让 Agent 使用 PaperSeek 处理一个具体研究问题：</p><blockquote><p>请使用 PaperSeek Skill 检索“开源软件融资如何影响软件维护”的相关文献。先检查本地安装；如果未安装，请在独立环境中安装并检查配置。使用 OpenAlex，保存检索记录，整理相关论文并附来源链接。</p></blockquote><p>Skill 会指导 Agent：</p><ol><li><strong>检查安装。</strong> 定位 <code>paperseek</code> 并查看版本，优先复用已有环境或可执行文件路径。</li><li><strong>按需安装。</strong> 使用 Python 3.12+ 与独立环境；有执行权限的 Agent 可以完成安装，否则提供步骤供你操作。</li><li><strong>检查配置。</strong> 执行 <code>paperseek doctor --json</code>，不发起真实检索；先解决缺少的必要模型或数据源配置。</li><li><strong>本地检索。</strong> 选择数据源，通过社区版 CLI 提交问题，并保留任务 ID、状态、警告与结果。</li></ol><p>已有安装不会自动升级，数据也不会自动迁移。更换版本时请遵循<a href="./../self-hosting/upgrade">升级指南</a>。</p><h2 id="配置模型与数据源" tabindex="-1">配置模型与数据源 <a class="header-anchor" href="#配置模型与数据源" aria-label="Permalink to &quot;配置模型与数据源&quot;">​</a></h2><p>通过本地进程环境，或 Agent 客户端的私有环境配置，提供模型连接与数据源凭据。Skill 使用与社区版相同的 <code>PAPERSEEK_*</code> 设置，详见<a href="./../reference/configuration">配置参考</a>、<a href="./../guide/models">模型设置</a>和<a href="./../guide/sources">数据源</a>。</p><p>不要将真实 Key 放入对话、<code>SKILL.md</code> 或提交到仓库的客户端配置。缺少必要值时，Agent 应说明配置项名称，并指导你在本地填写。</p><p>CLI 读取自身的进程环境。仅在网页表单中填写的值，不会自动配置另一个 Agent 进程；CLI 也不会自动加载 <code>.env</code> 文件。</p><h2 id="继续研究" tabindex="-1">继续研究 <a class="header-anchor" href="#继续研究" aria-label="Permalink to &quot;继续研究&quot;">​</a></h2><p>可以让 Agent 检查已保存的任务、归纳警告、读取规范化文献元数据，或协助导出结果。需要交互式筛选、历史记录和引用图谱时，可打开使用同一数据库的本地网页。</p><p>例如：</p><blockquote><p>打开刚才保存的 PaperSeek 检索任务，告诉我任务状态和使用的数据源，整理最相关的文献，并协助将结果导出为 CSV。</p></blockquote><p>相关性评分用于辅助筛选。使用生成的综合结论前，请核对原始研究；该 Skill 不会自动阅读论文 PDF，也不代表完成了系统综述。</p><h2 id="skill、mcp-与-http-api-如何选择" tabindex="-1">Skill、MCP 与 HTTP API 如何选择 <a class="header-anchor" href="#skill、mcp-与-http-api-如何选择" aria-label="Permalink to &quot;Skill、MCP 与 HTTP API 如何选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>适合的场景</th></tr></thead><tbody><tr><td><strong>Agent Skill</strong></td><td>Agent 可以运行本地命令，需要安装与使用 PaperSeek 的指导</td></tr><tr><td><a href="./mcp">MCP</a></td><td>助手通过结构化工具开始、查询、取消和导出检索任务</td></tr><tr><td><a href="./api">HTTP API</a></td><td>开发自己的应用，对接运行中的 PaperSeek 服务</td></tr></tbody></table><p>通过 Skill 使用 CLI 不需要安装 MCP，也不需要先启动网页服务。适合时，它也可以指导 Agent 使用已有本地 API 或同版本 MCP 集成。底层命令见<a href="./cli">CLI 指南</a>。</p>',25)])])}const g=t(o,[["render",i]]);export{c as __pageData,g as default};
